public class BusinessPartner { public int Id { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public string Type { get; set; } = "客户/供应商"; public string? Contact { get; set; } public string? Phone { get; set; } public string? Address { get; set; } public string? PostalCode { get; set; } public bool Active { get; set; } = true; }
public class Product { public int Id { get; set; } public string Sku { get; set; } = ""; public string Barcode { get; set; } = ""; public string Name { get; set; } = ""; public string Category { get; set; } = "通用物料"; public string Specification { get; set; } = "标准"; public string Unit { get; set; } = "件"; public decimal SafetyStock { get; set; } public decimal MaxStock { get; set; } public bool BatchManaged { get; set; } = true; public bool ExpiryManaged { get; set; } = false; public string IssueStrategy { get; set; } = "FIFO"; public bool Active { get; set; } = true; }
public class StockBalance { public int Id { get; set; } public int ProductId { get; set; } public int WarehouseId { get; set; } public int? LocationId { get; set; } public string BatchNo { get; set; } = "LEGACY-IMPORT"; public DateTime? ProducedAt { get; set; } public DateTime? ExpiryDate { get; set; } public string Status { get; set; } = "正常"; public DateTime ReceivedAt { get; set; } = DateTime.UtcNow; public decimal Quantity { get; set; } }
public class StockTransaction { public long Id { get; set; } public string DocumentNo { get; set; } = ""; public string? SourceDocumentNo { get; set; } public DateTime OccurredAt { get; set; } = DateTime.UtcNow; public string Type { get; set; } = "入库"; public int ProductId { get; set; } public int WarehouseId { get; set; } public decimal Quantity { get; set; } public string? Remark { get; set; } }
public class BusinessDocument { public long Id { get; set; } public string DocumentNo { get; set; } = ""; public string DocumentType { get; set; } = "入库单"; public DateTime DocumentDate { get; set; } = DateTime.UtcNow; public int? PartnerId { get; set; } public int WarehouseId { get; set; } public string Status { get; set; } = "草稿"; public string? Remark { get; set; } public string? CreatedBy { get; set; } public string? Auditor { get; set; } public DateTime? AuditedAt { get; set; } public DateTime? CompletedAt { get; set; } public List<BusinessDocumentLine> Lines { get; set; } = []; }
public class BusinessDocumentLine { public long Id { get; set; } public long DocumentId { get; set; } public int ProductId { get; set; } public string Barcode { get; set; } = ""; public decimal Quantity { get; set; } public int? LocationId { get; set; } public string? BatchNo { get; set; } public DateTime? ProducedAt { get; set; } public DateTime? ExpiryDate { get; set; } public string? Remark { get; set; } public string? QualityStatus { get; set; } }
public class Stocktake { public long Id { get; set; } public DateTime OccurredAt { get; set; } = DateTime.UtcNow; public int ProductId { get; set; } public int WarehouseId { get; set; } public decimal Before { get; set; } public decimal After { get; set; } public decimal Difference { get; set; } public string? Remark { get; set; } }
public class UserAccount { public string Username { get; set; } = ""; public string Password { get; set; } = ""; public string DisplayName { get; set; } = ""; public string Role { get; set; } = "操作员"; public string? RoleCode { get; set; } public int? DepartmentId { get; set; } public string? Phone { get; set; } public DateTime? LastLoginAt { get; set; } public int FailedLoginCount { get; set; } public DateTime? LockedUntil { get; set; } public bool Active { get; set; } = true; }
public class AuditLog { public long Id { get; set; } public DateTime OccurredAt { get; set; } = DateTime.UtcNow; public string? Username { get; set; } public string Action { get; set; } = ""; public string? EntityType { get; set; } public string? EntityId { get; set; } public string? Detail { get; set; } }
public record TransactionRequest(string Type, int ProductId, int WarehouseId, decimal Quantity, string? Remark); public record ProductRequest(string Sku, string Barcode, string Name, string Unit, decimal SafetyStock, decimal MaxStock = 0, string? Category = null, string? Specification = null); public record WarehouseRequest(string Code, string Name, string? Address); public record PartnerRequest(string Code, string Name, string Type); public record StocktakeRequest(int ProductId, int WarehouseId, decimal Actual, string? Remark); public record TransferRequest(int ProductId, int FromWarehouseId, int ToWarehouseId, decimal Quantity, string? Remark); public record LoginRequest(string Username, string Password); public record CaptchaChallenge(string Id, string ImageData); public record AuthLoginRequest(string Username, string Password, string CaptchaId, string CaptchaCode);
public record DocumentLineRequest(int ProductId, decimal Quantity, string? Barcode = null, int? LocationId = null, string? BatchNo = null, DateTime? ProducedAt = null, DateTime? ExpiryDate = null, string? QualityStatus = null, string? Remark = null); public record DocumentRequest(string DocumentType, int WarehouseId, int? PartnerId, List<DocumentLineRequest> Lines, string? Remark); public record LocationRequest(int WarehouseId, string Zone, string Shelf, string Level, string Code, decimal Capacity = 0); public record TransferDocumentRequest(int FromWarehouseId, int ToWarehouseId, List<DocumentLineRequest> Lines, string? Remark); public record StocktakeDocumentRequest(int WarehouseId, List<StocktakeLineRequest> Lines, string? Remark); public record StocktakeLineRequest(int ProductId, decimal ActualQuantity, int? LocationId = null, string? BatchNo = null); public record ReverseDocumentRequest(string? Remark);
public record DepartmentRequest(string Code, string Name, int? ParentId = null, string? ManagerUsername = null); public record RoleRequest(string Code, string Name, List<string>? Permissions = null); public record UserAssignmentRequest(string RoleCode, int? DepartmentId); public record ChangePasswordRequest(string CurrentPassword, string NewPassword);
public sealed class CaptchaService { readonly Dictionary<string, (string Code, DateTime Expires)> values = []; readonly object gate = new(); static readonly char[] alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789".ToCharArray(); public CaptchaChallenge Create() { var id = Guid.NewGuid().ToString("N"); var code = new string(Enumerable.Range(0, 4).Select(_ => alphabet[RandomNumberGenerator.GetInt32(alphabet.Length)]).ToArray()); lock (gate) values[id] = (code, DateTime.UtcNow.AddMinutes(5)); var svg = $"<svg xmlns='http://www.w3.org/2000/svg' width='150' height='48'><rect width='150' height='48' fill='#eef3f7'/><path d='M5 15L145 35M20 42L135 7' stroke='#8ba1b2' stroke-width='2'/><text x='75' y='34' text-anchor='middle' font-family='monospace' font-size='27' font-weight='700' letter-spacing='5' fill='#15324b'>{code}</text></svg>"; return new(id, "data:image/svg+xml;base64," + Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(svg))); } public bool Verify(string id, string code) { lock (gate) { if (!values.TryGetValue(id, out var v) || v.Expires < DateTime.UtcNow) return false; values.Remove(id); return string.Equals(v.Code, code?.Trim(), StringComparison.OrdinalIgnoreCase); } } }
public sealed class PasswordService { public string Hash(string p) { var s = RandomNumberGenerator.GetBytes(16); var h = Rfc2898DeriveBytes.Pbkdf2(p, s, 120000, HashAlgorithmName.SHA256, 32); return Convert.ToBase64String(s) + "." + Convert.ToBase64String(h); } public bool Verify(string p, string e) { try { var a = e.Split('.'); if (a.Length != 2) return p == e; var h = Rfc2898DeriveBytes.Pbkdf2(p, Convert.FromBase64String(a[0]), 120000, HashAlgorithmName.SHA256, 32); return CryptographicOperations.FixedTimeEquals(h, Convert.FromBase64String(a[1])); } catch { return false; } } }
public sealed class DataStore { public List<Warehouse> Warehouses { get; set; } = []; public List<Department> Departments { get; set; } = []; public List<RoleDefinition> Roles { get; set; } = []; public List<WarehouseLocation> Locations { get; set; } = []; public List<BusinessPartner> Partners { get; set; } = []; public List<Product> Products { get; set; } = []; public List<StockBalance> Stock { get; set; } = []; public List<StockTransaction> Transactions { get; set; } = []; public List<Stocktake> Stocktakes { get; set; } = []; public List<BusinessDocument> Documents { get; set; } = []; public List<TransferDocument> TransferDocuments { get; set; } = []; public List<StocktakeDocument> StocktakeDocuments { get; set; } = []; public List<UserAccount> Users { get; set; } = []; public List<AuditLog> AuditLogs { get; set; } = []; public int NextId() => Math.Max(0, Products.Select(x => x.Id).Concat(Warehouses.Select(x => x.Id)).Concat(Partners.Select(x => x.Id)).Concat(Stock.Select(x => x.Id)).Concat(Locations.Select(x => x.Id)).Concat(Departments.Select(x => x.Id)).DefaultIfEmpty().Max()) + 1; }
public sealed class DataStoreService
{
    readonly string sqlitePath; readonly object gate = new(); readonly PasswordService passwords = new();
    public DataStore Data { get; private set; }
    public DataStoreService(IWebHostEnvironment env) { sqlitePath = Path.Combine(env.ContentRootPath, "warehouse.sqlite"); Data = RelationalPersistence.LoadOrMigrate(sqlitePath) ?? new(); if (Data.Warehouses.Count == 0) Seed(); else EnsureDemoData(); foreach (var u in Data.Users) if (!u.Password.Contains('.')) u.Password = passwords.Hash(u.Password); var admin = Data.Users.SingleOrDefault(x => x.Username == "admin"); if (admin is not null && passwords.Verify("admin123", admin.Password)) admin.Password = passwords.Hash("admin"); Persist(); }
    void Seed() { Data.Warehouses = [new Warehouse { Id = 1, Code = "WH-001", Name = "中心仓库", Address = "总部园区" }]; Data.Products = [new Product { Id = 1000, Sku = "MAT-001", Barcode = "690100000001", Name = "纸箱", Category = "包装材料", Unit = "件", SafetyStock = 10, MaxStock = 100 }]; Data.Stock = [new StockBalance { Id = 2000, ProductId = 1000, WarehouseId = 1, Quantity = 50 }]; Data.Transactions = [new StockTransaction { Id = 1, DocumentNo = "IN-INIT-0001", Type = "入库", ProductId = 1000, WarehouseId = 1, Quantity = 50, Remark = "期初库存" }]; Data.Users = [new UserAccount { Username = "admin", Password = passwords.Hash("admin"), DisplayName = "系统管理员", Role = "管理员", RoleCode = "admin", DepartmentId = 1 }, new UserAccount { Username = "operator", Password = passwords.Hash("operator123"), DisplayName = "仓库操作员", Role = "仓库操作员", RoleCode = "warehouse_operator", DepartmentId = 3 }]; EnsureDemoData(); }
    void EnsureDemoData() { if (Data.Departments.Count == 0) Data.Departments = [new Department { Id = 1, Code = "HQ", Name = "总部" }, new Department { Id = 2, Code = "OPS", Name = "运营中心", ParentId = 1 }, new Department { Id = 3, Code = "WH", Name = "仓储部", ParentId = 2 }, new Department { Id = 4, Code = "FIN", Name = "财务部", ParentId = 1 }]; if (Data.Roles.Count == 0) Data.Roles = [new RoleDefinition { Code = "admin", Name = "系统管理员", Permissions = ["*"] }, new RoleDefinition { Code = "warehouse_manager", Name = "仓库主管", Permissions = ["inventory.read", "document.create", "document.submit", "document.approve", "transfer.manage", "stocktake.manage"] }, new RoleDefinition { Code = "warehouse_operator", Name = "仓库操作员", Permissions = ["inventory.read", "document.create", "document.submit"] }, new RoleDefinition { Code = "readonly", Name = "只读用户", Permissions = ["inventory.read", "report.read"] }]; var demo = new[] { (2, "WH-002", "华东成品仓", "上海市浦东新区"), (3, "WH-003", "华南原料仓", "广州市黄埔区"), (4, "WH-004", "西南周转仓", "成都市郫都区") }; foreach (var x in demo) if (!Data.Warehouses.Any(w => w.Code == x.Item2)) Data.Warehouses.Add(new Warehouse { Id = x.Item1, Code = x.Item2, Name = x.Item3, Address = x.Item4 }); if (!Data.Products.Any(p => p.Sku == "FG-001")) Data.Products.Add(new Product { Id = 1001, Sku = "FG-001", Barcode = "690100000002", Name = "成品礼盒", Category = "成品", Unit = "箱", SafetyStock = 20, MaxStock = 200, ExpiryManaged = true, IssueStrategy = "FEFO" }); if (!Data.Products.Any(p => p.Sku == "RAW-001")) Data.Products.Add(new Product { Id = 1002, Sku = "RAW-001", Barcode = "690100000003", Name = "塑料颗粒", Category = "原材料", Unit = "吨", SafetyStock = 5, MaxStock = 80 }); if (!Data.Stock.Any(s => s.WarehouseId == 2 && s.ProductId == 1001)) Data.Stock.Add(new StockBalance { Id = 2001, ProductId = 1001, WarehouseId = 2, BatchNo = "FG-20261001", ExpiryDate = DateTime.UtcNow.AddDays(18), ReceivedAt = DateTime.UtcNow.AddDays(-12), Quantity = 80 }); if (!Data.Stock.Any(s => s.WarehouseId == 3 && s.ProductId == 1002)) Data.Stock.Add(new StockBalance { Id = 2002, ProductId = 1002, WarehouseId = 3, BatchNo = "RAW-202609", ReceivedAt = DateTime.UtcNow.AddDays(-30), Quantity = 35 }); EnsureExpandedDemoData(); }
    void EnsureExpandedDemoData() { var warehouses = new[] { (5, "WH-005", "华北备件仓", "北京市顺义区"), (6, "WH-006", "西北原料仓", "西安市高新区"), (7, "WH-007", "华中配送仓", "武汉市东西湖区") }; foreach (var x in warehouses) if (!Data.Warehouses.Any(w => w.Code == x.Item2)) Data.Warehouses.Add(new Warehouse { Id = x.Item1, Code = x.Item2, Name = x.Item3, Address = x.Item4 }); var categories = new[] { ("包装材料", "件"), ("成品", "箱"), ("原材料", "吨"), ("备件", "个"), ("办公用品", "盒") }; for (var i = 3; i < 100; i++) { var sku = $"DEMO-{i + 1:000}"; if (!Data.Products.Any(p => p.Sku == sku)) { var c = categories[i % categories.Length]; Data.Products.Add(new Product { Id = 1000 + i, Sku = sku, Barcode = $"69010000{i + 1:0000}", Name = $"演示商品{i + 1:000}", Category = c.Item1, Unit = c.Item2, SafetyStock = 5 + (i % 15), MaxStock = 100 + (i % 5) * 50, BatchManaged = true, ExpiryManaged = i % 4 == 0, IssueStrategy = i % 4 == 0 ? "FEFO" : "FIFO" }); } } foreach (var p in Data.Products.Where(x => x.Active).ToList()) { if (!Data.Stock.Any(s => s.ProductId == p.Id)) { var warehouseId = 1 + (p.Id % 7); var expiry = p.ExpiryManaged ? DateTime.UtcNow.AddDays(15 + (p.Id % 120)) : (DateTime?)null; Data.Stock.Add(new StockBalance { Id = 3000 + p.Id, ProductId = p.Id, WarehouseId = warehouseId, BatchNo = $"BATCH-{p.Id}", ProducedAt = DateTime.UtcNow.AddDays(-30), ExpiryDate = expiry, ReceivedAt = DateTime.UtcNow.AddDays(-10), Quantity = 20 + (p.Id % 81) }); Data.Transactions.Add(new StockTransaction { Id = Data.Transactions.Count + 1, DocumentNo = $"IN-DEMO-{p.Id}", Type = "入库", ProductId = p.Id, WarehouseId = warehouseId, Quantity = 20 + (p.Id % 81), Remark = "演示期初库存" }); } } }
    void Persist() { lock (gate) RelationalPersistence.Save(sqlitePath, Data); }
    public void Backup(string destination) { lock (gate) RelationalPersistence.Backup(sqlitePath, destination); }
    public void Audit(string? username, string action, string? entityType = null, string? entityId = null, string? detail = null) => Mutate(d => d.AuditLogs.Add(new AuditLog { Id = d.AuditLogs.Count + 1, Username = username, Action = action, EntityType = entityType, EntityId = entityId, Detail = detail }));
    public void Mutate(Action<DataStore> action) { lock (gate) { action(Data); RelationalPersistence.Save(sqlitePath, Data); } }
}
